// Content-Security-Policy and security headers for Next.js. Generated by `eos scaffold web-security`;
// yours to edit, and a human must review every change (it is a security control).
// Policy = the strict nonce example from the Next.js CSP guide (verified 2026-10-10):
// https://nextjs.org/docs/app/guides/content-security-policy . Every third-party origin you add (analytics,
// fonts, images, APIs) is a trust decision: add it to the narrowest directive, never as a wildcard.
// Trade-off: nonces need dynamic rendering (no static or CDN-cached HTML). With Cache Components (cacheComponents:
// true) a prerendered page has no nonce and its scripts are blocked: add `export const instant = false` to the
// routes this policy covers (checked on Next 16.4; e2e/security-headers.spec.ts fails on any violation).
// See .eos/packs/ref/frontend/web-security.md.

// next/image renders style="color:transparent"; nonces do not cover style attributes, so allow that one hash.
const NEXT_IMAGE_STYLE = "'sha256-zlqnbDt84zf1iSefLU/ImC54isoprH/MRiVZGskwexk='";

export function createNonce(): string {
  return Buffer.from(crypto.randomUUID()).toString("base64");
}

export function buildCsp(nonce: string, opts: { dev?: boolean; reportUri?: string } = {}): string {
  const directives = [
    "default-src 'self'",
    // React needs 'unsafe-eval' in development only (error stack reconstruction).
    `script-src 'self' 'nonce-${nonce}' 'strict-dynamic'${opts.dev ? " 'unsafe-eval'" : ""}`,
    `style-src 'self' 'nonce-${nonce}' 'unsafe-hashes' ${NEXT_IMAGE_STYLE}`,
    "img-src 'self' blob: data:",
    "font-src 'self'",
    "object-src 'none'",
    "base-uri 'self'",
    "form-action 'self'",
    "frame-ancestors 'none'",
    "upgrade-insecure-requests",
  ];
  if (opts.reportUri) directives.push(`report-uri ${opts.reportUri}`);
  return directives.join("; ");
}

// Values follow the OWASP HTTP Headers cheat sheet (.eos/packs/ref/security/web-api-hardening.md).
// HSTS only takes effect over HTTPS; add "; preload" only after reading hstspreload.org's requirements.
export const securityHeaders: Record<string, string> = {
  "Strict-Transport-Security": "max-age=63072000; includeSubDomains",
  "X-Content-Type-Options": "nosniff",
  "Referrer-Policy": "strict-origin-when-cross-origin",
  "Permissions-Policy": "camera=(), microphone=(), geolocation=()",
};
